// מצפה ל־body בסגנון:
// {
//   "userId": "uuid-from-supabase",
//   "messages": [
//     { "role": "user", "content": "תסכם לי את האימון האחרון" }
//   ],
//   "activeWorkoutId": null,
//   "timezone": "Asia/Jerusalem"
// }

const body = $json.body || $json;

const userId = body.userId || null;
const messages = body.messages || [];
const activeWorkoutId = body.activeWorkoutId || null;
const timezone = body.timezone || "Asia/Jerusalem";

// נזהה את ההודעה האחרונה של המשתמש
let lastUserMessage = "שלום, מה תרצה לדעת על האימונים שלך?";
for (let i = messages.length - 1; i >= 0; i--) {
  if (messages[i].role === "user") {
    lastUserMessage = messages[i].content;
    break;
  }
}

return [
  {
    json: {
      userId,
      activeWorkoutId,
      timezone,
      lastUserMessage,
      messages
    }
  }
];

// אחרי הרצה אחת של Coach AI Brain, תבדוק ב-Execution Data
// איך בדיוק נראה האובייקט. בינתיים ננסה לתפוס שדות נפוצים.

let aiOutput = "";

// אפשרויות נפוצות – שנה לפי מה שתראה:
if ($json.text) {
  aiOutput = $json.text;
} else if ($json.answer) {
  aiOutput = $json.answer;
} else if ($json.data && typeof $json.data === "string") {
  aiOutput = $json.data;
} else if ($json.choices && $json.choices[0]?.message?.content) {
  aiOutput = $json.choices[0].message.content;
} else {
  aiOutput = $input.first().json.output;
}

return [
  {
    json: {
      message: aiOutput,
      meta: {
        usedTools: [],
        language: "he"
      }
    }
  }
];

const workouts = $items("Supabase Workouts").map(item => item.json);

return [
  {
    json: {
      userId: $node["Prepare Request"].json.userId,
      lastUserMessage: $node["Prepare Request"].json.lastUserMessage,
      workouts,
    },
  },
];
